using System;using System.IO;using System.Drawing;using System.Windows.Forms;using System.Reflection;using System.Diagnostics;using System.Collections.Generic;using FleetLab;
// Natural complete ending -> menu through production MainForm callbacks, SILENT device.
class NaturalMenuCheck {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 static object Field(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}static object Prop(object o,string n){return o.GetType().GetProperty(n,F).GetValue(o,null);}static void Call(object o,string n,params object[] a){o.GetType().GetMethod(n,F).Invoke(o,a);}static void Require(bool b,string s){if(!b)throw new Exception(s);}
 sealed class Silent:IClipOutput{readonly WaveOutput wave=new WaveOutput();public int Starts;public bool Disposed;public bool Active{get{return wave.Active;}}public int Samples{get{return wave.Samples;}}public void Start(short[] p,int at){wave.Start(new short[p.Length],at);Starts++;}public void Pause(){wave.Pause();}public void Resume(){wave.Resume();}public void Stop(){wave.Stop();}public void Dispose(){wave.Dispose();Disposed=true;}}
 [STAThread]static int Main(string[] a){if(a.Length!=2)return 2;string assets=Path.GetFullPath(a[0]),dest=Path.GetFullPath(a[1]);Directory.CreateDirectory(dest);int errors=0;var rows=new List<string>{"Outcome,ElapsedMs,EndingEvents,MenuFactor,Turn"};Application.SetUnhandledExceptionMode(UnhandledExceptionMode.CatchException);Application.ThreadException+=delegate{errors++;};Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);var total=Stopwatch.StartNew();try{
  using(var form=new MainForm(assets)){
   typeof(MainForm).GetField("previewMode",F).SetValue(form,true);form.ShowInTaskbar=false;form.StartPosition=FormStartPosition.Manual;form.Location=new Point(-20000,-20000);((Audio)Field(form,"sound")).Enabled=false;((ClipStudy)Field(form,"clip")).SetSound(false);((ClipStudy)Field(form,"battleMovie")).SetSound(false);var player=(EndingPlayer)Field(form,"ending");player.SetSound(false);var movie=(ClipStudy)Field(player,"Movie");((IClipOutput)Field(movie,"output")).Dispose();var device=new Silent();movie.GetType().GetField("output",F).SetValue(movie,device);player.SetSound(true);var tabs=(TabControl)Field(form,"tabs");var front=Field(form,"front");form.Show();Application.DoEvents();((Button)Field(form,"auto")).PerformClick();((Button)Field(form,"start")).PerformClick();var game=form.State;int turn=game.Turn,events=game.Events.Count;
   foreach(bool victory in new[]{true,false}){
    tabs.SelectedIndex=3;player.StartOutcome(victory);string name=victory?"VICTORY":"LOSE";var watch=Stopwatch.StartNew();bool paused=false;long resume=0;int frame=0;
    while(!(tabs.SelectedIndex==4&&(int)Prop(front,"Factor")==64&&!(bool)Prop(front,"Revealing"))){Application.DoEvents();var timeline=(EndingTimeline)Prop(player,"Timeline");var clip=(ClipTimeline)Prop(movie,"Timeline");Require(errors==0&&player.Problem==""&&movie.Problem=="","Playback/focus error");Require(form.State==game&&game.Paused&&game.Turn==turn&&game.Events.Count==events,"Menu/result mutated paused game");if(resume>0){Require(clip.Frame==frame&&!timeline.Playing,"Movie pause advanced");if(watch.ElapsedMilliseconds>=resume){((Button)Field(player,"PlayButton")).PerformClick();resume=0;}}
     else if(victory&&!paused&&timeline.Phase==EndingPhase.Movie&&clip.Frame>=10){player.Pause();paused=true;frame=clip.Frame;resume=watch.ElapsedMilliseconds+350;}Require(watch.ElapsedMilliseconds<55000,"Natural menu timeout");System.Threading.Thread.Sleep(8);}
    var end=(EndingTimeline)Prop(player,"Timeline");Require(end.Phase==EndingPhase.Complete&&end.Trace.Count==54&&!device.Active,"Once-only ending completion/cleanup");Require(watch.ElapsedMilliseconds>(victory?33050:34000)+6240+680+560-100,"Early menu handoff");using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(0,0,form.Width,form.Height));bmp.Save(Path.Combine(dest,name+"-Menu.png"));}rows.Add(name+","+watch.ElapsedMilliseconds+","+end.Trace.Count+","+Prop(front,"Factor")+","+turn);File.WriteAllLines(Path.Combine(dest,"Handoffs.csv"),rows.ToArray());
   }
   Require(device.Starts==2,"Movie buffer starts");Call(front,"Activate",3);((Button)Field(front,"QuitButton")).PerformClick();Application.DoEvents();Require(form.IsDisposed&&device.Disposed&&!device.Active&&errors==0,"Original-menu Quit did not release resources/exit cleanly");File.WriteAllText(Path.Combine(dest,"Result.txt"),"PASS both natural ending-to-menu handoffs through MainForm; SILENT waveOut, two finite buffers, one350msmovie pause, original54event prefixes, title reveal, preserved paused battle, inline-confirmed Quit and clean disposal. ThreadException=0. ElapsedSeconds="+total.ElapsedMilliseconds/1000+". No skips/seeks/accelerated time. Native menu actions beyond initialization use documented modern bridges; audible/physical checks remain separate.");
  }return 0;
 }catch(Exception e){File.WriteAllText(Path.Combine(dest,"Result.txt"),"FAIL "+e);return 1;}}
